import os
import json
from builtins import str
import ast

try:
    from taf.ul.trs_e2e_fw.lib.oam.admin.admin_factory import AdminBaseClass
except Exception as e:
    print("e:", e)
from taf.ul.trs_e2e_fw.lib.utils.logger.robotbackgroundlogger import BackgroundLogger
from taf.ul.trs_e2e_fw.lib.utils.resource_file import get_resource_file
from robot.libraries.BuiltIn import BuiltIn

logger = BackgroundLogger.Instance()


class RcConnection(AdminBaseClass):

    def __init__(self):
        super(RcConnection, self).__init__()

    def set_autoconnection_parameters(self, **kwargs):
        """
        set_autoconnection_parameters(*args, **kwargs)
            Set autoconnection transport params.

            Parameters:
                timeout (Union[int,str]) - Timeout for the operation, defaults to 120.
                connection (Union[AdminConnection,str]) - AdminConnection object or if used, string name alias.
                rc_ac_param_file (string) - json file that contains different autoconnection profiles which is placed in resource folder
                rc_ac_profile (string) - profile name to be used, from rc_ac_param_file

            Returns:
                str: status "Succeeded" or "Failed"
        """
        ac_profile = kwargs["rc_ac_profile"]
        timeout = kwargs.pop('timeout', 10)
        connection = kwargs.pop('alias', 'default')
        param_file = kwargs.pop("rc_ac_param_file", "rc_ac_param.json")
        base_path = os.path.dirname(BuiltIn().get_variable_value("${SUITE SOURCE}"))
        param_file = os.path.join(base_path, 'resources', param_file)

        rc_ac_param_file = get_resource_file(param_file)
        with open(rc_ac_param_file) as json_file:
                rc_ac_param = json.load(json_file)["rc_ac_parameters"][ac_profile]
        # convert string to int for integer values
        int_param_list = ["primary_prefix_length", "secondary_prefix_length", "secondary_vlan_id", "server_port", "primary_vlan_id",
                          "secondary_vlan_id","ike_identity_to_use"]

        for param in rc_ac_param:
            if param in int_param_list:
                try:
                    if type(rc_ac_param[param]) is str or type(rc_ac_param[param]) is unicode:
                        rc_ac_param[param] = ast.literal_eval(str(rc_ac_param[param]))
                except NameError:
                    try:
                        rc_ac_param[param] = ast.literal_eval(str(rc_ac_param[param]))
                    except Exception as int_e:
                        logger.debug("Reading int value failed: {}.\n.Please pass a proper integer value".format(str(int_e)))

        # may require if boolean type input in parameters are there in json file convert string to bool for boolean values
        # try:
        #     if type(rc_ac_param["act_cert_validation"]) is str or type(trs_ac_param["act_cert_validation"]) is unicode:
        #         trs_ac_param["act_cert_validation"] = bool(trs_ac_param["act_cert_validation"])
        # except NameError:
        #     try:
        #         trs_ac_param["act_cert_validation"] = bool(trs_ac_param["act_cert_validation"])
        #     except Exception as bool_e:
        #         logger.debug("Reading act_cert_validation value failed: {}.\n.Please pass a proper bool value".format(str(bool_e)))

        # with open(rc_ac_param_file) as json_file:
        #         new_rc_ac_param = json.load(json_file)["rc_ac_parameters"][ac_profile]["kw_accepted_parameters"]

        logger.info("The parameters in the profile are: {}".format(rc_ac_param))
        try:
            return self.factory.rcconnect.set_autoconnection(timeout=timeout, connection=connection, **rc_ac_param)
        except Exception as err:
             print("error: {}".format(err))
             raise Exception("set Autoconnection failed due to : {} ".format(err))
             #logger.debug("Successfully set autoconnection parameters, navigating to pnp status page of webem")
             AdminBaseClass.tear_flag=False

    def set_autoconnection_parameters_to_default(self, **kwargs):
        timeout = kwargs.pop('timeout', 10)
        connection = kwargs.pop('alias', 'default')
        self.factory.rcconnect.set_autoconnection_parameters_to_default(timeout=timeout, connection=connection)

    def switch_autoconfiguration_service_rc(self, **kwargs):
        return getattr(self, '_{}_autoconfiguration_service'.format(kwargs['operation'].lower()))(**kwargs)

    def switch_autoconnection_service_rc(self, **kwargs):
        return getattr(self, '_{}_autoconnection_service'.format(kwargs['operation'].lower()))(**kwargs)

    def _enable_autoconfiguration_service(self, **kwargs):
        timeout = kwargs.get('timeout', 100)
        connection = kwargs.get('alias', 'default')
        return self.factory.rcconnect.enable_autoconfiguration_service(timeout=timeout, connection=connection)

    def _enable_autoconnection_service(self, **kwargs):
        timeout = kwargs.get('timeout', 100)
        connection = kwargs.get('alias', 'default')
        return self.factory.rcconnect.enable_autoconnection_service(timeout=timeout, connection=connection)

    def _disable_autoconfiguration_service(self, **kwargs):
        timeout = kwargs.get('timeout', 100)
        connection = kwargs.get('alias', 'default')
        return self.factory.rcconnect.disable_autoconfiguration_service(timeout=timeout, connection=connection)

    def _disable_autoconnection_service(self, **kwargs):
        timeout = kwargs.get('timeout', 100)
        connection = kwargs.get('alias', 'default')
        return self.factory.rcconnect.disable_autoconnection_service(timeout=timeout, connection=connection)